#include <iostream>
#include <vector>

// Khai báo nguyên mẫu với từ khóa inline
inline void dtcvhcn(int a, int b, int &dt, int &cv);

struct HinhChuNhat {
    int a;
    int b;
    int dt;
    int cv;
};

int main() {
    int n = 0;
    if (!(std::cin >> n) || n <= 0) {
        return 0;
    }

    std::vector<HinhChuNhat> ds(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> ds[i].a >> ds[i].b;
        dtcvhcn(ds[i].a, ds[i].b, ds[i].dt, ds[i].cv);
    }

    for (int i = 0; i < n; ++i) {
        std::cout << "Hinh chu nhat " << (i + 1) << ":\n";
        std::cout << "  Canh: " << ds[i].a << " va " << ds[i].b << "\n";
        std::cout << "  Dien tich: " << ds[i].dt << "\n";
        std::cout << "  Chu vi: " << ds[i].cv << "\n";
    }

    return 0;
}

// Định nghĩa hàm inline phía sau main
inline void dtcvhcn(int a, int b, int &dt, int &cv) {
    dt = a * b;
    cv = 2 * (a + b);
}
